"""Public facade: the one-object surface a Source Bus producer uses.

``SourceProducer.connect()`` is the composition root for the library — it wires
the gRPC source client and the session, then opens one source-scoped
connection. The customer's hot loop only calls ``send_*`` (non-blocking).
"""

from __future__ import annotations

import uuid

from loop_sdk.source.domain.camera import OnCameraOpen
from loop_sdk.source.domain.config import OnSelectRobotConfig
from loop_sdk.source.domain.frame import (
    MarkerFrame,
    RobotFrame,
    RobotStateValue,
    TactileChannelValue,
    TactileFrame,
)
from loop_sdk.source.domain.schema import SourceSchema
from loop_sdk.source.domain.stats import SendStats
from loop_sdk.source.outbound.grpc_source_client import GrpcSourceClient
from loop_sdk.source.service.producer_session import ProducerSession
from loop_sdk.source.setup.config import SourceConfig


class SourceProducer:
    """A connected Source Bus producer for one declared schema."""

    def __init__(self, session: ProducerSession) -> None:
        self._session = session

    @classmethod
    def connect(
        cls,
        loop_addr: str,
        source: SourceSchema,
        config: SourceConfig | None = None,
        client_id: str | None = None,
        on_select: OnSelectRobotConfig | None = None,
        on_camera_open: OnCameraOpen | None = None,
    ) -> SourceProducer:
        """Open a connection to the Loop Source Bus and begin answering its commands.

        ``loop_addr`` is the Source Bus's ``host:port``. ``source`` declares the
        one source this SDK connection will stream. Recording start/stop is operator-driven; the
        SDK starts streaming when the Source Bus opens a session.

        ``on_select`` is the robot config apply callback. When a robot source
        advertises ``available_options``, the Source Bus selects one config and
        sends it on Open; ``on_select(requested)`` reconfigures the device and
        returns the config it actually applied (``None`` = applied as requested;
        raising fails the source). Omit it when no robot source negotiates a config.

        ``on_camera_open`` is the camera control-plane callback. When Loop sends
        a camera Open command, it can start or reconfigure the helper-owned RTSP
        server and return the applied setting and optional replacement RTSP
        endpoint. Camera frames are still pulled by Loop over RTSP/RTP.
        """
        settings = config or SourceConfig()
        client = GrpcSourceClient(
            loop_addr=loop_addr,
            client_id=client_id or uuid.uuid4().hex,
            version=settings.client_version,
            reconnect_backoff_seconds=settings.reconnect_backoff_seconds,
            reconnect_backoff_max_seconds=settings.reconnect_backoff_max_seconds,
            on_select=on_select,
            on_camera_open=on_camera_open,
        )
        session = ProducerSession(source, client)
        session.start()
        return cls(session)

    @property
    def source_id(self) -> str | None:
        """Server-assigned runtime source id after registration acceptance."""
        return self._session.source_id

    def send_robot(
        self,
        timestamp_us: int,
        sequence: int,
        state: dict[str, RobotStateValue],
    ) -> None:
        """Send one robot-state sample as named channel readings. Non-blocking.

        ``state`` maps the source's declared channel keys to heterogeneous
        readings (scalar/vector/int/bool/string). Omit a key (or map it to
        ``None``) for "no reading this sample"."""
        self._session.send(RobotFrame(timestamp_us=timestamp_us, sequence=sequence, state=state))

    def send_tactile(
        self,
        timestamp_us: int,
        sequence: int,
        channels: tuple[TactileChannelValue, ...],
    ) -> None:
        """Send one tactile sample. Non-blocking."""
        self._session.send(
            TactileFrame(timestamp_us=timestamp_us, sequence=sequence, channels=channels)
        )

    def send_marker(self, timestamp_us: int, sequence: int, label: str, category: str = "") -> None:
        """Send one sparse marker sample. Non-blocking."""
        self._session.send(
            MarkerFrame(
                timestamp_us=timestamp_us,
                sequence=sequence,
                label=label,
                category=category,
            )
        )

    def report_source_error(self, code: str, message: str = "") -> None:
        """Report a source fault. The Source Bus maps it to ``SourceEvent(FAILED)``
        so the recorder fails that source fast. Best-effort, non-blocking."""
        self._session.report_error(code, message)

    def stats(self) -> SendStats:
        """Return a snapshot of delivery and connection statistics."""
        return self._session.stats()

    def close(self) -> None:
        """Stop sending and tear the connection down."""
        self._session.close()

    def __enter__(self) -> SourceProducer:
        return self

    def __exit__(self, *_exc: object) -> None:
        self.close()
